class Student { final String id, studentId, name, phone, guardian, guardianPhone, status; final String? photoUrl; Student({required this.id,required this.studentId,required this.name,required this.phone,required this.guardian,required this.guardianPhone,required this.status,this.photoUrl}); factory Student.fromMap(Map<String,dynamic> m)=>Student(id:'${m['id']}',studentId:'${m['student_id']??''}',name:'${m['full_name']??m['name']??''}',phone:'${m['phone']??''}',guardian:'${m['guardian_name']??''}',guardianPhone:'${m['guardian_phone']??''}',status:'${m['status']??'active'}',photoUrl:m['photo_url'] as String?); }
class Course { final String id,name,status; final double fee; Course({required this.id,required this.name,required this.status,required this.fee}); factory Course.fromMap(Map<String,dynamic> m)=>Course(id:'${m['id']}',name:'${m['name']??''}',status:'${m['status']??'active'}',fee:(m['fee'] as num?)?.toDouble()??0); }
class Batch { final String id,name; final String? courseId,teacherId,room,startDate,endDate,status; final double fee; Batch({required this.id,required this.name,this.courseId,this.teacherId,this.room,this.startDate,this.endDate,this.status='active',this.fee=0}); factory Batch.fromMap(Map<String,dynamic> m)=>Batch(id:'${m['id']}',name:'${m['name']??''}',courseId:m['course_id'] as String?,teacherId:m['teacher_id'] as String?,room:m['room'] as String?,startDate:m['start_date'] as String?,endDate:m['end_date'] as String?,status:'${m['status']??'active'}',fee:(m['fee'] as num?)?.toDouble()??0); }
